#!/usr/bin/env node
/**
 * 校验 values 是否覆盖 manifest 中所有 key，并可选对比磁盘上的生成物是否一致。
 */
import fs from "node:fs";
import path from "node:path";
import {
  REPO_ROOT,
  buildTargetContent,
  loadManifest,
  loadProfileValues,
  parseEnvFile,
  resolveTargetValue,
} from "./lib.mjs";

function validateProfile(profile, manifest) {
  const profileConfig = manifest.profiles?.[profile];
  if (!profileConfig?.targets) {
    throw new Error(`Manifest has no targets for profile "${profile}".`);
  }

  const sharedValues = loadProfileValues(profile);
  const errors = [];

  for (const [targetName, targetConfig] of Object.entries(profileConfig.targets)) {
    const overrides = targetConfig.overrides ?? {};
    for (const key of targetConfig.keys) {
      const value = resolveTargetValue(key, sharedValues, overrides);
      if (value === undefined) {
        errors.push(`${profile} / ${targetName}: missing value for ${key}`);
      }
    }

    const expected = buildTargetContent(targetName, targetConfig, sharedValues);
    const absolutePath = path.join(REPO_ROOT, targetName);
    if (!fs.existsSync(absolutePath)) {
      errors.push(`${targetName}: file missing (run pnpm env:sync)`);
      continue;
    }

    const onDisk = fs.readFileSync(absolutePath, "utf8");
    const normalizedExpected = expected.replace(/\r\n/g, "\n");
    const normalizedDisk = onDisk.replace(/\r\n/g, "\n");

    if (normalizedDisk.startsWith("# GENERATED BY pnpm env:sync")) {
      if (normalizedDisk !== normalizedExpected) {
        errors.push(`${targetName}: out of date (run pnpm env:sync)`);
      }
      continue;
    }

    const expectedEntries = parseEnvFile(expected).entries;
    const diskEntries = parseEnvFile(onDisk).entries;
    for (const key of targetConfig.keys) {
      if (expectedEntries[key] !== diskEntries[key]) {
        errors.push(
          `${targetName}: key ${key} differs from SSOT (legacy file or run pnpm env:sync)`,
        );
      }
    }
  }

  return errors;
}

function main() {
  const manifest = loadManifest();
  const profiles = Object.keys(manifest.profiles ?? {});
  const allErrors = [];

  for (const profile of profiles) {
    allErrors.push(...validateProfile(profile, manifest));
  }

  if (allErrors.length > 0) {
    console.error("env:check failed:\n");
    for (const line of allErrors) {
      console.error(`  - ${line}`);
    }
    process.exit(1);
  }

  console.log("env:check passed.");
}

try {
  main();
} catch (error) {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
}
